/**
 * 로케일 숫자 서식 (표기 규칙) — 통화 · 자릿수 구분자 · 소수점 · 자릿수.
 *
 * ⚠ 표기 계층 전용. 저장은 항상 최소단위(g/ml/개)·풀정밀도이고, 확정값은 packages/db RPC 가 권위다.
 *   서식은 계산 "결과를 보여줄 때"만 적용하며, 어떤 경우에도 계산 입력으로 되돌아가지 않는다.
 *
 * 축 분리 — 무엇을 누가 정하는가
 *   로케일이 정한다(사실, 선택 대상 아님) : 자릿수 구분자 · 소수점 문자 · 통화기호 · 금액 소수 자릿수
 *   사용자가 정한다(취향)                 : 단가 소수 자릿수 — 단위 설정(MY-04). 기본값은 여기서 파생.
 *   같은 미터법 안에서도 서식이 갈리므로(독일 1.250,50 / 멕시코 1,250.50) 단위 시스템과는 독립 축이다.
 *
 * Intl.NumberFormat 을 쓰지 않는 이유: Hermes(안드로이드)의 Intl 은 플랫폼 ICU 에 의존해 기기마다
 * 결과가 달라질 수 있다. 원가·손익 숫자는 기기와 무관하게 같아야 하므로 테이블로 고정한다.
 */

/** 지역까지 분화된 서식 키 (언어 8 · 지역 분화 2 = 10). */
export type LocaleKey =
  | 'ko' | 'en-US' | 'ja' | 'de' | 'ar-SA' | 'ar-AE' | 'vi' | 'es-ES' | 'es-MX' | 'pt-BR';

/** 스크립트·폰트 판정용 언어 코드 (apps/mobile theme/fonts.ts 의 AppLocale 과 동일 집합). */
export type LocaleLang = 'ko' | 'en' | 'ja' | 'de' | 'ar' | 'vi' | 'es' | 'pt';

export interface LocaleFormat {
  key: LocaleKey;
  lang: LocaleLang;
  /** 설정 화면 표기 (한국어). */
  label: string;
  /** 해당 언어 표기 — 언어 목록에서 자기 언어로 보이도록. */
  native: string;
  /** 통화 ISO 코드 · 이름 · 기호. */
  currency: string;
  currencyName: string;
  symbol: string;
  /** 기호 위치 — 'pre' = $1,250.50 · 'post' = 1.250,50 € */
  symbolPos: 'pre' | 'post';
  /** 후치 기호 앞 공백 (유럽식 € 표기). */
  symbolSpace: boolean;
  /** 자릿수 구분자 · 소수점 문자. 둘은 항상 서로 다르다. */
  group: string;
  decimal: string;
  /** 금액 소수 자릿수 = 통화 최소단위. 원·엔·동 = 0, 그 외 = 2. */
  moneyDigits: number;
  /** 오른쪽에서 왼쪽으로 쓰는 표기. */
  rtl: boolean;
}

// 아랍어 문자열은 테이블 밖 상수로 뺀다 — RTL 문자를 표 안에 섞으면 에디터에서 그 행의 앞뒤가 뒤집혀 보여
// 정렬이 깨지고 diff 를 읽기 어렵다. 값 자체는 그대로다.
const AR_SA = 'العربية (السعودية)'; // 아랍어 (사우디아라비아)
const AR_AE = 'العربية (الإمارات)'; // 아랍어 (UAE)
const SYM_SAR = 'ر.س'; // 리얄 기호
const SYM_AED = 'د.إ'; // 디르함 기호

/**
 * 서식 테이블. 금액 자릿수는 통화가, 구분자는 지역이 정한다.
 * 단가 자릿수는 여기 두지 않는다 — moneyDigits + 2 로 파생되고 사용자가 덮어쓸 수 있다(unitPriceDigits).
 */
export const LOCALES: readonly LocaleFormat[] = [
  { key: 'ko',    lang: 'ko', label: '한국어',                   native: '한국어',             currency: 'KRW', currencyName: 'Won',    symbol: '원',    symbolPos: 'post', symbolSpace: false, group: ',', decimal: '.', moneyDigits: 0, rtl: false },
  { key: 'en-US', lang: 'en', label: '영어 (미국)',              native: 'English (US)',       currency: 'USD', currencyName: 'Dollar', symbol: '$',     symbolPos: 'pre',  symbolSpace: false, group: ',', decimal: '.', moneyDigits: 2, rtl: false },
  { key: 'ja',    lang: 'ja', label: '일본어',                   native: '日本語',              currency: 'JPY', currencyName: 'Yen',    symbol: '¥',     symbolPos: 'pre',  symbolSpace: false, group: ',', decimal: '.', moneyDigits: 0, rtl: false },
  { key: 'de',    lang: 'de', label: '독일어 (독일·오스트리아)', native: 'Deutsch',            currency: 'EUR', currencyName: 'Euro',   symbol: '€',     symbolPos: 'post', symbolSpace: true,  group: '.', decimal: ',', moneyDigits: 2, rtl: false },
  { key: 'ar-SA', lang: 'ar', label: '아랍어 (사우디아라비아)',  native: AR_SA,                currency: 'SAR', currencyName: 'Riyal',  symbol: SYM_SAR, symbolPos: 'post', symbolSpace: true,  group: ',', decimal: '.', moneyDigits: 2, rtl: true },
  { key: 'ar-AE', lang: 'ar', label: '아랍어 (UAE)',             native: AR_AE,                currency: 'AED', currencyName: 'Dirham', symbol: SYM_AED, symbolPos: 'post', symbolSpace: true,  group: ',', decimal: '.', moneyDigits: 2, rtl: true },
  { key: 'vi',    lang: 'vi', label: '베트남어',                 native: 'Tiếng Việt',         currency: 'VND', currencyName: 'Dong',   symbol: '₫',     symbolPos: 'post', symbolSpace: false, group: ',', decimal: '.', moneyDigits: 0, rtl: false },
  { key: 'es-ES', lang: 'es', label: '스페인어 (스페인)',        native: 'Español (España)',   currency: 'EUR', currencyName: 'Euro',   symbol: '€',     symbolPos: 'post', symbolSpace: true,  group: '.', decimal: ',', moneyDigits: 2, rtl: false },
  { key: 'es-MX', lang: 'es', label: '스페인어 (멕시코)',        native: 'Español (México)',   currency: 'MXN', currencyName: 'Peso',   symbol: '$',     symbolPos: 'pre',  symbolSpace: false, group: ',', decimal: '.', moneyDigits: 2, rtl: false },
  { key: 'pt-BR', lang: 'pt', label: '포르투갈어 (브라질)',      native: 'Português (Brasil)', currency: 'BRL', currencyName: 'Real',   symbol: 'R$',    symbolPos: 'pre',  symbolSpace: false, group: '.', decimal: ',', moneyDigits: 2, rtl: false },
] as const;

export const DEFAULT_LOCALE: LocaleKey = 'ko';

const BY_KEY: Record<string, LocaleFormat> = Object.fromEntries(LOCALES.map((l) => [l.key, l]));

/** 서식 조회. 미등록 키는 기본 로케일로 폴백 — 표기가 절대 깨지지 않게. */
export function getLocale(key: LocaleKey = DEFAULT_LOCALE): LocaleFormat {
  return BY_KEY[key] ?? BY_KEY[DEFAULT_LOCALE]!;
}

/**
 * 단가 소수 자릿수 기본값 = 금액 자릿수 + 2.
 * 단가는 최소단위(g/ml/개) 기준이라 금액보다 두 자리 잘다. 한국 4.71원/g(2자리) · 미국 $0.0047/g(4자리).
 * 사용자가 단위 설정에서 0~4 로 덮어쓸 수 있고, 그 값이 있으면 이 함수 대신 그 값을 쓴다.
 */
export function unitPriceDigits(key: LocaleKey = DEFAULT_LOCALE): number {
  return getLocale(key).moneyDigits + 2;
}

/** 선택 가능한 단가 자릿수 (단위 설정 UI). */
export const UNIT_PRICE_DIGIT_OPTIONS = [0, 1, 2, 3, 4] as const;

/**
 * 기본 표시 예시 — 언어·통화 설정에서 서식을 한눈에 보여주는 견본. 통화기호는 붙이지 않는다.
 * 소수를 쓰는 통화에만 .50 을 붙여 소수점 문자를 드러낸다. 0자리 통화(원·엔·동)에 1,250.5 를 넣으면
 * 1,251 로 반올림돼 견본 구실을 못 하므로 1,250 을 쓴다.
 * 검산: 한국 1,250 · 미국 1,250.50 · 독일 1.250,50
 */
export function localeSample(key: LocaleKey = DEFAULT_LOCALE): string {
  const L = getLocale(key);
  return formatNumber(L.moneyDigits > 0 ? 1250.5 : 1250, { digits: L.moneyDigits, group: L.group, decimal: L.decimal });
}

/**
 * 숫자 → 서식 문자열. 반올림 후 고정 자릿수로 채우고 세 자리마다 구분자를 넣는다.
 * 유한수가 아니면 0 으로 취급 — 표기 계층이 화면을 깨뜨리지 않게.
 */
export function formatNumber(value: number, opts: { digits: number; group: string; decimal: string }): string {
  const { digits, group, decimal } = opts;
  const v = Number.isFinite(value) ? value : 0;
  const neg = v < 0;
  const fixed = Math.abs(v).toFixed(digits); // 반올림 + 자릿수 채움
  const [intPart = '0', decPart = ''] = fixed.split('.');
  const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, group);
  return (neg ? '-' : '') + grouped + (decPart ? decimal + decPart : '');
}

/** 통화기호 부착 — 음수 부호는 항상 기호 바깥(-$1,250.50). */
function withSymbol(body: string, L: LocaleFormat, neg: boolean): string {
  const s = L.symbolPos === 'pre' ? L.symbol + body : body + (L.symbolSpace ? ' ' : '') + L.symbol;
  return (neg ? '-' : '') + s;
}

/** 금액 표기 — 판매가·매출·고정지출 등. 자릿수는 통화가 정한다(12,000원 · $1,250.50). */
export function formatMoney(value: number, key: LocaleKey = DEFAULT_LOCALE): string {
  const L = getLocale(key);
  const v = Number.isFinite(value) ? value : 0;
  return withSymbol(formatNumber(Math.abs(v), { digits: L.moneyDigits, group: L.group, decimal: L.decimal }), L, v < 0);
}

/**
 * 단가 표기 — 최소단위 기준(4.71원/g). digits 미지정 시 로케일 기본값(금액 + 2).
 * baseUnit 은 저장 최소단위 문자열(g·ml·개)을 그대로 붙인다.
 */
export function formatUnitPrice(
  value: number,
  baseUnit: string,
  key: LocaleKey = DEFAULT_LOCALE,
  digits: number = unitPriceDigits(key),
): string {
  const L = getLocale(key);
  const v = Number.isFinite(value) ? value : 0;
  return withSymbol(formatNumber(Math.abs(v), { digits, group: L.group, decimal: L.decimal }), L, v < 0) + '/' + baseUnit;
}

/**
 * 비율 표기 — 절사(내림). 경계에서 반올림과 갈린다: 33.45% → 33.4%(반올림이면 33.5%).
 * ⚠ 반올림하면 33.5% 가 되어 검산 기준값 표기와 어긋난다. 자릿수 설정 대상이 아니다(1자리 고정).
 * 부동소수 오차 보정용 epsilon: 0.313 × 1000 = 312.9999… 가 312 로 내려가는 것을 막는다.
 */
export function formatPercent(ratio: number, key: LocaleKey = DEFAULT_LOCALE, digits = 1): string {
  const L = getLocale(key);
  const r = Number.isFinite(ratio) ? ratio : 0;
  const f = 10 ** digits;
  const v = Math.floor(Math.abs(r) * 100 * f + 1e-9) / f;
  return (r < 0 ? '-' : '') + formatNumber(v, { digits, group: L.group, decimal: L.decimal }) + '%';
}

/**
 * 서식 문자열 → 숫자. 사용자 입력 파싱용(독일 "1.250,50" → 1250.5).
 * 구분자를 먼저 제거한 뒤 소수점 문자를 '.' 로 통일한다 — 순서가 바뀌면 독일식에서 정수부가 뭉개진다.
 */
export function parseNumber(text: string, key: LocaleKey = DEFAULT_LOCALE): number {
  const L = getLocale(key);
  const cleaned = text
    .split(L.group).join('')
    .split(L.decimal).join('.')
    .replace(/[^\d.-]/g, '');
  const n = parseFloat(cleaned);
  return Number.isFinite(n) ? n : 0;
}

/**
 * 레시피 원가·손익 계산 — ② 3장, ⑤ 2.3.
 * 1인분 소요량 = 입력량 ÷ N. 재료 원가 = Σ(1인분량 × 기준단가).
 * 순이익 = 판매가 − 세금 − 재료 − 고정 − 추가.
 * 권장 판매가 = (재료+추가) ÷ (1 − 세금비율 − 고정지출률 − 목표).
 */
import type { TaxItem } from '@margincook/types';
import { isNonNegativeFinite, isPositiveFinite } from './guards';

/**
 * 1인분 소요량 = 입력량(N인분) ÷ N.
 * 인분이 0 이하이거나 입력량이 음수·비유한이면 산출 불가(null) — Infinity 로 전파시키지 않는다.
 */
export function perServingQty(inputQty: number, servings: number): number | null {
  if (!isNonNegativeFinite(inputQty)) return null;
  if (!isPositiveFinite(servings)) return null;
  return inputQty / servings;
}

/**
 * 세금 비율(판매가 대비 0~1) = **사장님이 적은 항목의 합**(0090).
 *
 * 부가세도 항목 하나다. 포함/별도/면세 세 갈래는 없앴다 — 답해야 할 질문이
 * 하나 더 생기는 것이었다. 항목이 없으면 0이고, 그게 면세다.
 *
 * ⚠ 부가세 포함 가격이면 요율은 10 이 아니라 **10/110 = 9.0909…** 다.
 * SQL `tax_of()` 와 같은 공식이다 — 한쪽만 고치면 안 된다(절대원칙 3).
 */
export function taxRate(items: readonly TaxItem[] = []): number {
  let rate = 0;
  for (const i of items) {
    // 0 이하·비유한 요율은 없는 항목으로 본다. SQL 의 `where rate > 0` 과 같다.
    if (!isPositiveFinite(i?.rate)) continue;
    rate += i.rate / 100;
  }
  return rate;
}

/** 세금액 = 판매가 × 세금 비율. */
export function taxAmount(price: number, items: readonly TaxItem[] = []): number {
  if (!isNonNegativeFinite(price)) return 0; // 음수·비유한 판매가에서 음수 세금을 만들지 않는다
  return price * taxRate(items);
}

/** 항목별 내역 — 화면이 '(−) 세금'을 펼칠 때 쓴다. SQL `tax_breakdown()` 미러. */
export function taxBreakdown(
  price: number,
  items: readonly TaxItem[] = [],
): { name: string; rate: number; amount: number; builtin: boolean }[] {
  const p = isNonNegativeFinite(price) ? price : 0;
  const out: { name: string; rate: number; amount: number; builtin: boolean }[] = [];
  // 0090: 기본 항목은 없다. 부가세도 사장님이 적은 줄 하나다.
  for (const i of items) {
    if (!isPositiveFinite(i?.rate)) continue;
    out.push({ name: i.name, rate: i.rate, amount: (p * i.rate) / 100, builtin: false });
  }
  return out;
}

export interface RecipeLineInput {
  inputQty: number; // N인분 기준 입력량(기준단위)
  baseUnitPrice: number | null; // 기준 단가(원/기준단위). null이면 잠정(0 취급, '?')
}

export interface ProfitInput {
  price: number; // 판매가
  servings: number; // 기준 인분 N
  /** 세금 항목(0090). 부가세도 여기 한 줄이다. 없으면 세금 0원 — 그게 면세다. */
  taxItems?: readonly TaxItem[];
  lines: RecipeLineInput[];
  extraPerServing: number; // 추가 지출 합(1인분 정액)
  fixedRate: number | null; // 고정지출률(0~1). null이면 0% 잠정(A-04)
}

export interface ProfitResult {
  price: number;
  tax: number;
  materialCost: number;
  extraCost: number;
  fixedCost: number;
  profit: number;
  profitRate: number; // 0~1
  materialRate: number; // 0~1
  hasMissingPrice: boolean; // 단가 미입력 재료 포함 → 잠정치
}

/** 재료 원가(1인분) = Σ(1인분량 × 기준단가). 단가 null은 0으로 잠정. */
export function materialCost(lines: RecipeLineInput[], servings: number): {
  cost: number;
  hasMissingPrice: boolean;
} {
  let cost = 0;
  let hasMissingPrice = false;
  for (const l of lines) {
    // 단가 미입력은 잠정(0원 취급) — SQL 의 coalesce(base_unit_price, 0) 와 같은 값이 된다.
    if (l.baseUnitPrice == null || !isNonNegativeFinite(l.baseUnitPrice)) {
      hasMissingPrice = true;
      continue;
    }
    // 입력량·인분이 오염되면 그 라인을 원가에 더하지 않고 잠정으로 표시한다.
    // (음수 입력량을 더하면 원가가 깎여 순이익이 과대 계상된다.)
    const per = perServingQty(l.inputQty, servings);
    if (per === null) {
      hasMissingPrice = true;
      continue;
    }
    cost += per * l.baseUnitPrice;
  }
  return { cost, hasMissingPrice };
}

/** 손익 계산. 검산: 제육 → profit 4,046.69원, rate 0.3372. */
export function computeProfit(input: ProfitInput): ProfitResult {
  const { servings, taxItems, lines } = input;
  // 음수·비유한 판매가는 0으로 정규화한다. 음수 매출은 도메인상 존재하지 않고,
  // 그대로 흘리면 세금·고정지출·순이익률이 전부 뒤집힌다.
  const price = isNonNegativeFinite(input.price) ? input.price : 0;
  const extraPerServing = isNonNegativeFinite(input.extraPerServing) ? input.extraPerServing : 0;
  const rawFixedRate = input.fixedRate ?? 0;
  const fixedRate = isNonNegativeFinite(rawFixedRate) ? rawFixedRate : 0;
  const tax = taxAmount(price, taxItems ?? []);
  const mat = materialCost(lines, servings);
  const fixedCost = fixedRate * price;
  const profit = price - tax - mat.cost - extraPerServing - fixedCost;
  return {
    price,
    tax,
    materialCost: mat.cost,
    extraCost: extraPerServing,
    fixedCost,
    profit,
    profitRate: price > 0 ? profit / price : 0,
    materialRate: price > 0 ? mat.cost / price : 0,
    hasMissingPrice: mat.hasMissingPrice,
  };
}

/**
 * 권장 판매가 (② 3.6) = (재료+추가) ÷ (1 − 세금비율 − 고정지출률 − 목표순이익률).
 * 세금 항목이 비면 0, 부가세 포함 가격이면 1/11(=10/110)처럼 호출자가 매장 기준을
 * 명시적으로 넘긴다. 기본값을 두면 "세금 없음"을 과거 부가세 시나리오로 오인한다.
 * 분모 ≤ 0이면 산출 불가(null).
 * 검산: 제육 (2835+300)/(1−1/11−0.313−0.40) ≈ 15,986 → 16,000
 */
export function recommendedPrice(
  materialPlusExtra: number,
  fixedRate: number,
  targetProfitRate: number,
  taxRatio: number,
): number | null {
  const denom = 1 - taxRatio - fixedRate - targetProfitRate;
  return denom > 0 ? materialPlusExtra / denom : null;
}

-- ════════════════════════════════════════════════════════════════
-- 0014 · 매출관리 스키마 (SALES-01~18)
--
-- 배경:
--   매출관리 탭 전체가 화면만 있고 **저장할 테이블이 없었다**. DB 19개 테이블 어디에도
--   일별 판매·채널별 매출·메뉴별 판매량을 담을 곳이 없어, 앱은 demoData 상수만 그리고 있었다.
--
-- 설계 원칙:
--   1) **판매 사실만 저장하고 파생값은 저장하지 않는다.** 매출·원가·순이익은 판매 기록과
--      기준단가·고정지출률에서 계산한다. 파생값을 저장하면 원본이 바뀔 때 조용히 어긋난다.
--      (예외: 확정 스냅샷은 profit_trends/monthly_pl 이 이미 담당한다.)
--   2) **날짜는 항상 명시한다.** `sale_date` 에 기본값을 두지 않는다 —
--      과거 영업일 데이터를 입력해야 매출 분석에 기간 비교가 생긴다.
--      기본값을 두면 "오늘"로 조용히 채워져 과거 등록이 막힌다.
--   3) 채널은 테이블로 둔다. 수수료율이 매장마다 다르고 시간이 지나며 바뀐다.
--
-- ⚠ 폐기 손실은 여기 두지 않는다. 이미 `inventory_events(type='discard')` 가 원장이며,
--   `occurred_at` 으로 기간 집계한다. 같은 사실을 두 곳에 저장하지 않는다.
-- ════════════════════════════════════════════════════════════════

-- ── 판매 채널 (매장 / 배달 / 포장 …) ──────────────────────────
create table if not exists public.sales_channels (
  id          uuid primary key default gen_random_uuid(),
  store_id    uuid not null references stores (id) on delete cascade,
  code        text not null,                                   -- 'hall' | 'delivery' | 'takeout' | 매장 자유 코드
  name        text not null,                                   -- 화면 표기 ('매장')
  fee_rate    numeric(5,2) not null default 0
                check (fee_rate >= 0 and fee_rate < 100),       -- 수수료율(%) — 중개+결제 합산
  fee_note    text,                                            -- '중개 6.8% · 결제 3.0%' 같은 내역 설명
  sort_order  int not null default 0,
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (store_id, code)
);
create index if not exists sales_channels_store_idx on public.sales_channels (store_id, sort_order);

comment on table public.sales_channels is '판매 채널과 수수료율. 채널별 손익 분해(SALES-18)의 기준.';

-- ── 일별 매출 헤더 ────────────────────────────────────────────
-- 하루치 "장부 한 장". 메뉴별 판매는 아래 items 에 붙는다.
create table if not exists public.daily_sales (
  id            uuid primary key default gen_random_uuid(),
  store_id      uuid not null references stores (id) on delete cascade,
  sale_date     date not null,                                 -- ★ 기본값 없음(과거 등록 허용)
  etc_revenue   numeric not null default 0 check (etc_revenue >= 0),
                -- 레시피 미등록 매출(음료 등). 메뉴별 합산에 잡히지 않는 금액.
  daily_extra   numeric not null default 0 check (daily_extra >= 0),
                -- 그날 한 번 발생한 현금 지출. 고정 지출과 구분된다.
  note          text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (store_id, sale_date)                                 -- 하루 한 장
);
create index if not exists daily_sales_store_date_idx on public.daily_sales (store_id, sale_date desc);

comment on table public.daily_sales is
  '일별 매출 장부 한 장. sale_date 는 기본값이 없다 — 과거 영업일도 명시 입력해야 기간 분석이 가능하다.';

-- ── 메뉴별 판매 (채널별 수량) ─────────────────────────────────
create table if not exists public.daily_sales_items (
  id             uuid primary key default gen_random_uuid(),
  store_id       uuid not null references stores (id) on delete cascade,
  daily_sales_id uuid not null references daily_sales (id) on delete cascade,
  recipe_id      uuid references recipes (id) on delete set null,
                 -- 레시피가 지워져도 판매 사실은 남는다(원장은 append-only 성격).
  menu_name      text not null,                                -- 판매 시점 메뉴명 스냅샷
  unit_price     numeric not null check (unit_price >= 0),     -- 판매 시점 판매가 스냅샷
  qty_hall       numeric not null default 0 check (qty_hall >= 0),
  qty_delivery   numeric not null default 0 check (qty_delivery >= 0),
  qty_takeout    numeric not null default 0 check (qty_takeout >= 0),
  created_at     timestamptz not null default now()
);
create index if not exists daily_sales_items_parent_idx on public.daily_sales_items (daily_sales_id);
create index if not exists daily_sales_items_recipe_idx on public.daily_sales_items (recipe_id);

comment on table public.daily_sales_items is
  '메뉴별·채널별 판매 수량. 판매가와 메뉴명은 **판매 시점 스냅샷**이다 — 나중에 레시피 판매가를 바꿔도 과거 매출이 변하면 안 된다.';

comment on column public.daily_sales_items.unit_price is
  '판매 시점 판매가. recipes.price 를 참조하지 않고 복사한다(과거 매출 불변).';

-- ── RLS — 다른 테이블과 동일한 store_id 격리 ──────────────────
do $$
declare t text;
begin
  foreach t in array array['sales_channels','daily_sales','daily_sales_items'] loop
    execute format('alter table %I enable row level security;', t);
    execute format($f$create policy %1$s_select on %1$I for select
                     using (store_id in (select public.my_store_ids()));$f$, t);
    execute format($f$create policy %1$s_insert on %1$I for insert
                     with check (store_id in (select public.my_store_ids()));$f$, t);
    execute format($f$create policy %1$s_update on %1$I for update
                     using (store_id in (select public.my_store_ids()))
                     with check (store_id in (select public.my_store_ids()));$f$, t);
    execute format($f$create policy %1$s_delete on %1$I for delete
                     using (store_id in (select public.my_store_ids()));$f$, t);
  end loop;
end $$;

-- ── updated_at 갱신 트리거 (0001 의 touch_updated_at 재사용) ──
do $$
begin
  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = 'public' and p.proname = 'touch_updated_at') then
    execute 'create trigger daily_sales_touch before update on public.daily_sales
             for each row execute function public.touch_updated_at()';
  end if;
end $$;

-- ── 기간 손익 집계 함수 ───────────────────────────────────────
-- 화면(SALES-02 매출 분석)이 기간을 골라 호출한다. 파생값을 저장하지 않고 매번 계산한다.
--
-- 계산 규칙 (앱 표시와 일치해야 한다):
--   매출     = Σ(단가 × 총수량) + 기타매출
--   재료원가 = Σ(1인분 재료원가 × 수량)      ← 레시피 라인 × base_unit_price
--   수수료   = Σ(채널 매출 × 채널 수수료율)
--   폐기손실 = inventory_events(discard) 의 폐기량 × 기준단가
--   고정지출 = 월 고정지출률 × 기간 매출
--   세금     = 부가세 포함 메뉴의 판매가 × 10/110
create or replace function public.sales_summary(
  p_store uuid,
  p_from  date,
  p_to    date
) returns jsonb language plpgsql stable security invoker as $$
declare
  v_revenue   numeric := 0;
  v_etc       numeric := 0;
  v_material  numeric := 0;
  v_fee       numeric := 0;
  v_tax       numeric := 0;
  v_waste     numeric := 0;
  v_extra     numeric := 0;
  v_fixed     numeric := 0;
  v_qty       numeric := 0;
  v_days      int     := 0;
  v_rate      numeric;
begin
  -- 메뉴 판매 기반 집계
  select
    coalesce(sum(it.unit_price * (it.qty_hall + it.qty_delivery + it.qty_takeout)), 0),
    coalesce(sum(it.qty_hall + it.qty_delivery + it.qty_takeout), 0)
  into v_revenue, v_qty
  from daily_sales ds join daily_sales_items it on it.daily_sales_id = ds.id
  where ds.store_id = p_store and ds.sale_date between p_from and p_to;

  select coalesce(sum(etc_revenue), 0), coalesce(sum(daily_extra), 0), count(*)
    into v_etc, v_extra, v_days
  from daily_sales where store_id = p_store and sale_date between p_from and p_to;

  v_revenue := v_revenue + v_etc;

  -- 재료 원가 = Σ(메뉴 1인분 재료원가 × 판매 수량)
  select coalesce(sum(
           (it.qty_hall + it.qty_delivery + it.qty_takeout) *
           coalesce((select sum((rl.input_qty / r.base_servings) * coalesce(base_unit_price(rl.ingredient_id), 0))
                       from recipe_lines rl where rl.recipe_id = r.id), 0)
         ), 0)
    into v_material
  from daily_sales ds
  join daily_sales_items it on it.daily_sales_id = ds.id
  join recipes r on r.id = it.recipe_id
  where ds.store_id = p_store and ds.sale_date between p_from and p_to;

  -- 채널 수수료 = Σ(채널별 매출 × 수수료율)
  select coalesce(sum(
           it.unit_price * (
             it.qty_hall     * coalesce((select fee_rate from sales_channels where store_id=p_store and code='hall'), 0) +
             it.qty_delivery * coalesce((select fee_rate from sales_channels where store_id=p_store and code='delivery'), 0) +
             it.qty_takeout  * coalesce((select fee_rate from sales_channels where store_id=p_store and code='takeout'), 0)
           ) / 100.0
         ), 0)
    into v_fee
  from daily_sales ds join daily_sales_items it on it.daily_sales_id = ds.id
  where ds.store_id = p_store and ds.sale_date between p_from and p_to;

  -- 세금 — 부가세 포함 메뉴만 판매가 × 10/110
  select coalesce(sum(
           case when r.tax_mode = 'included'
                then it.unit_price * (it.qty_hall + it.qty_delivery + it.qty_takeout) * 10 / 110
                else 0 end), 0)
    into v_tax
  from daily_sales ds
  join daily_sales_items it on it.daily_sales_id = ds.id
  join recipes r on r.id = it.recipe_id
  where ds.store_id = p_store and ds.sale_date between p_from and p_to;

  -- 폐기 손실 — 재고 원장에서 집계(같은 사실을 매출 테이블에 복제하지 않는다)
  select coalesce(sum(coalesce(ev.volume_delta, 0) * coalesce(base_unit_price(ev.ingredient_id), 0)), 0)
    into v_waste
  from inventory_events ev
  where ev.store_id = p_store and ev.type = 'discard'
    and (ev.occurred_at at time zone business_tz())::date between p_from and p_to;

  -- 고정 지출 — 기간 시작 월의 고정지출률 × 기간 매출.
  -- (기간이 여러 달에 걸치면 월별 안분이 필요하다 → 2차 과제로 남긴다.)
  v_rate := fixed_cost_rate(p_store, to_char(p_from, 'YYYY-MM'));
  v_fixed := coalesce(v_rate, 0) * v_revenue;

  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'days', v_days,
    'revenue', v_revenue, 'etc_revenue', v_etc, 'qty', v_qty,
    'material_cost', v_material, 'channel_fee', v_fee, 'tax', v_tax,
    'waste_loss', v_waste, 'daily_extra', v_extra, 'fixed_cost', v_fixed,
    -- 고정지출률이 없으면(해당 월 미입력) 잠정임을 알린다 — 0% 로 확정하지 않는다(가이드 P0-5).
    'fixed_rate_provisional', (v_rate is null),
    'profit', v_revenue - v_material - v_fee - v_tax - v_waste - v_extra - v_fixed
  );
end;
$$;

comment on function public.sales_summary(uuid, date, date) is
  '기간 손익 집계. 파생값을 저장하지 않고 판매 기록·기준단가·고정지출률에서 매번 계산한다.';

-- ════════════════════════════════════════════════════════════════
-- 0149 · 과거 기준은 과거 것이다 (기획서 §6.4)
--
-- 정정 RPC 는 "다시 열지 않고 고친다" 를 지켰지만, **고칠 때 무엇을 기준으로 쓰는지**
-- 를 안 정했다. 그래서 두 곳이 현재를 봤다.
--
--   ① 기타 매출 세금이 **현재 세율**로 다시 계산됐다.
--      실측: 저장된 2,636.36원(9.0909%) → 세율을 20% 로 바꾼 뒤 같은 내용을 그대로
--      다시 보내니 5,800원. 사장님은 아무것도 안 고쳤는데 과거 세금과 손익이 움직였다.
--   ② **현재 판매 중지한 메뉴**의 과거 수량을 못 고쳤다.
--      실측: 제육볶음을 판매 중지하니 3일 전 수량 수정이 22000 으로 거절됐다.
--      과거 정정은 지금 파는지가 아니라 **그날 무엇이 있었는지**를 따라야 한다.
--
-- 규칙:
--   · 기타 매출 내용이 같으면 세금도 그대로 둔다 — 계산 자체를 안 한다.
--   · 금액을 고칠 때는 **그날 저장된 세율**을 쓴다.
--   · 그날 세율이 기록에 없으면 현재 세율을 쓰되 `basis_quality = estimated_current` 로
--     내린다. 화면은 `원가·손익은 현재 기준으로 계산했어요` 를 그때 보여 준다.
--   · 앞으로 만드는 스냅샷에는 `etc_tax_rate` 를 담는다.
-- ════════════════════════════════════════════════════════════════

-- ── ① 스냅샷에 그날 기타매출 세율을 담는다 ──────────────────────
/*
 * 메뉴 세금은 `recipes` 항목마다 `tax` 로 굳어 있는데, 기타 매출은 굳는 곳이 없었다.
 * 매출 자체는 사장님이 적은 실제 기록이고 세율만 매장 설정이라 그날 값이 필요하다.
 */
create or replace function public.build_day_snapshot(p_store uuid, p_date date)
returns jsonb
language sql
stable
as $fn$
  select jsonb_build_object(
    'taken_at', now(),
    'fixed_rate', coalesce(fixed_cost_rate(p_store, to_char(p_date, 'YYYY-MM')), 0),
    'fixed_items', coalesce(
      (select f.items from fixed_costs_monthly f
        where f.store_id = p_store and f.month = to_char(p_date, 'YYYY-MM')), '[]'::jsonb),
    -- 기타 매출에 매길 세율(0149). 메뉴 세금과 달리 굳는 곳이 여기밖에 없다.
    'etc_tax_rate', store_tax_rate(p_store),
    -- 재료 단가 — 폐기 손실과 재료 되짚기가 그날 값을 쓰려면 여기 있어야 한다(0058).
    'ingredients', coalesce((
      select jsonb_object_agg(i.id::text, jsonb_build_object(
               'name', i.name, 'base_unit', i.base_unit,
               'unit_price', base_unit_price(i.id)))
        from ingredients i where i.store_id = p_store), '{}'::jsonb),
    'recipes', coalesce((
      select jsonb_object_agg(r.id::text, recipe_snapshot_entry(r.id))
        from recipes r where r.store_id = p_store and r.active), '{}'::jsonb));
$fn$;

comment on function public.build_day_snapshot(uuid, date) is
  '그날의 기준값 한 벌 — 고정지출·기타매출 세율·재료 단가·메뉴. 한 번 정해지면 그날 안 움직인다(0062·0149).';

create or replace function public.day_etc_tax_rate(p_store uuid, p_date date)
returns numeric
language sql
stable
as $fn$
  -- 그날 스냅샷에 담긴 기타매출 세율. 없으면 null — 부르는 쪽이 어떻게 할지 정한다.
  select (snapshot->>'etc_tax_rate')::numeric
    from business_days
   where store_id = p_store and business_date = p_date;
$fn$;

comment on function public.day_etc_tax_rate(uuid, date) is
  '그날 기타매출 세율(0149). 스냅샷에 없으면 null 이고, 그때는 현재 세율을 쓰되 basis_quality 를 estimated_current 로 내린다.';

revoke execute on function public.day_etc_tax_rate(uuid, date) from public, anon;
grant  execute on function public.day_etc_tax_rate(uuid, date) to authenticated, service_role;


-- ── ② 기타 매출 세금은 그날 세율을 따른다 ───────────────────────
create or replace function public.apply_sale_items(
  p_store       uuid,
  p_date        date,
  p_sales       uuid,
  p_items       jsonb,
  p_etc_items   jsonb,
  p_extra_items jsonb,
  p_allow_closed boolean default false
) returns jsonb
language plpgsql
as $fn$
declare
  v_item      jsonb;
  v_result    jsonb := '[]'::jsonb;
  v_etc       numeric;
  v_etc_tax   numeric;
  v_extra     numeric;
  v_cur_items jsonb;
  v_rate      numeric;
  v_estimated boolean := false;
begin
  /*
   * ⚠ **전체 교체가 아니다**(0117). 안 보낸 메뉴는 그대로 둔다.
   *   지울 때는 0 을 명시해서 보낸다.
   */
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    v_result := v_result || jsonb_build_array(
      e10_sale_recorded(
        p_store, p_date, (v_item->>'recipe_id')::uuid,
        coalesce((v_item->>'qty_hall')::numeric, 0),
        coalesce((v_item->>'qty_delivery')::numeric, 0),
        coalesce((v_item->>'qty_takeout')::numeric, 0),
        coalesce((v_item->>'qty_waste')::numeric, 0),
        p_allow_closed));
  end loop;

  /*
   * ⚠ 기타/지출은 배열 통째 교체다. 항목 단위 병합은 하지 않는다 — 같은 이름이
   *   여럿일 수 있어 무엇이 같은 항목인지 정할 수 없다.
   * ⚠ `updated_at` 은 **여기서 안 찍는다**(0148). 부르는 쪽이 실제 변경을 확인한
   *   뒤에 한 번만 찍는다. 그리고 값이 같으면 UPDATE 자체를 안 돌린다 —
   *   `touch_updated_at` 트리거가 UPDATE 마다 시각을 다시 찍기 때문이다.
   */
  if p_etc_items is not null then
    select etc_items into v_cur_items from daily_sales where id = p_sales;

    /*
     * ⚠ **내용이 같으면 손대지 않는다**(0149). 화면은 고친 칸만 보내지 않고 화면에
     *   있는 값을 통째로 보낸다. 여기서 현재 세율로 다시 계산하면 사장님이 아무것도
     *   안 고쳤는데 과거 세금이 움직인다 — 실측 2,636.36원 → 5,800원.
     */
    if v_cur_items is distinct from p_etc_items then
      -- 합계는 항목에서 **계산**한다. 화면이 보낸 합계를 믿으면 둘이 어긋난다.
      select coalesce(sum(coalesce((x->>'price')::numeric,0) * coalesce((x->>'qty')::numeric,1)), 0)
        into v_etc from jsonb_array_elements(p_etc_items) x;

      -- 금액을 고칠 때는 **그날 세율**로 매긴다.
      v_rate := day_etc_tax_rate(p_store, p_date);
      if v_rate is null then
        /*
         * 그날 세율이 기록에 없다(0149 이전에 열린 장부, 또는 정정이 만든 장부).
         * 현재 세율로 계산하되 **그렇게 했다고 남긴다.** 조용히 현재값을 쓰면
         * 나중에 그 숫자가 무엇이었는지 되짚을 수 없다.
         */
        v_rate      := store_tax_rate(p_store);
        v_estimated := p_allow_closed;
      end if;
      v_etc_tax := round(v_etc * v_rate, 2);

      update daily_sales
         set etc_items = p_etc_items, etc_revenue = v_etc, etc_tax = v_etc_tax
       where id = p_sales
         and (etc_items   is distinct from p_etc_items
           or etc_revenue is distinct from v_etc
           or etc_tax     is distinct from v_etc_tax);
    end if;
  end if;

  if p_extra_items is not null then
    select coalesce(sum(coalesce((x->>'amount')::numeric,0)), 0)
      into v_extra from jsonb_array_elements(p_extra_items) x;
    update daily_sales
       set extra_items = p_extra_items, daily_extra = v_extra
     where id = p_sales
       and (extra_items is distinct from p_extra_items
         or daily_extra is distinct from v_extra);
  end if;

  -- 현재 세율을 빌려 썼다면 그날 기준은 더 이상 그날 것이 아니다.
  if v_estimated then
    update business_days
       set basis_quality = 'estimated_current'
     where store_id = p_store and business_date = p_date
       and basis_quality <> 'estimated_current';
  end if;

  return v_result;
end $fn$;

revoke execute on function public.apply_sale_items(uuid, date, uuid, jsonb, jsonb, jsonb, boolean)
  from public, anon, authenticated, service_role;


-- ── ③ 종료된 장부에도 기준을 더할 수 있다 ───────────────────────
/*
 * §6.4 의 `판매 내역 추가` 는 그날 기준에 없는 메뉴로도 들어온다 — 그때 만든 메뉴,
 * 그때 꺼 뒀던 메뉴. 여기서 막으면 그 화면 자체가 성립하지 않는다.
 * 더하는 것은 **순수 추가**라 이미 기록된 숫자를 안 움직인다(0062). 다만 더한 값은
 * 그날 값이 아니라 지금 값이므로 그 장부는 `estimated_current` 로 내린다.
 *
 * ⚠ 인자를 더하면 `create or replace` 가 **덮어쓰지 않고 겹치기를 만든다.**
 *   옛 서명을 먼저 지운다(assert_no_rpc_overloads 가 잡아 준 적이 있다).
 */
drop function if exists public.add_to_day_basis(uuid, date, uuid);

create or replace function public.add_to_day_basis(
  p_store uuid, p_date date, p_recipe uuid, p_allow_closed boolean default false)
returns jsonb language plpgsql security invoker as $fn$
declare
  v_day   business_days;
  v_entry jsonb;
begin
  select * into v_day from business_days
   where store_id = p_store and business_date = p_date
   for update;

  if v_day.id is null then
    raise exception '아직 영업을 시작하지 않았어요' using errcode = '45001', detail = 'BEFORE_OPEN';
  end if;
  if v_day.status = 'closed' and not p_allow_closed then
    raise exception '% 영업이 종료되어 판매를 저장할 수 없어요', p_date
      using errcode = '45002', detail = 'DAY_CLOSED';
  end if;

  -- 이미 있으면 그대로 둔다. 다시 넣으면 오늘 기준이 지금 값으로 바뀐다 —
  -- 그게 바로 막으려던 일이다(불변식: 한 번 정해진 기준은 그날 안 움직인다).
  v_entry := v_day.snapshot #> array['recipes', p_recipe::text];
  if v_entry is not null then
    return v_entry;
  end if;

  v_entry := recipe_snapshot_entry(p_recipe);
  if v_entry is null then
    -- 레시피 자체가 없다. 화면이 분기할 수 있게 **안정된 코드**로 돌려준다(0149).
    raise exception '그날 기준에도 없고 지금도 없는 메뉴예요'
      using errcode = '45013', detail = 'BASIS_NOT_AVAILABLE';
  end if;

  update business_days
     set snapshot = jsonb_set(
           -- 이 메뉴가 쓰는 재료 중 오늘 기준에 없는 것(영업 중에 만든 재료)도 함께 담는다.
           jsonb_set(snapshot, '{ingredients}',
             coalesce(snapshot->'ingredients', '{}'::jsonb) || coalesce((
               select jsonb_object_agg(i.id::text, jsonb_build_object(
                        'name', i.name, 'base_unit', i.base_unit,
                        'unit_price', base_unit_price(i.id)))
                 from recipe_lines l join ingredients i on i.id = l.ingredient_id
                where l.recipe_id = p_recipe and l.ingredient_id is not null
                  and not (coalesce(snapshot->'ingredients', '{}'::jsonb) ? i.id::text)),
               '{}'::jsonb)),
           array['recipes', p_recipe::text], v_entry, true)
   where id = v_day.id;

  -- 종료된 장부에 **지금 값**을 더했다. 그 장부의 기준은 더 이상 그날 것이 아니다.
  if v_day.status = 'closed' then
    update business_days set basis_quality = 'estimated_current'
     where id = v_day.id and basis_quality <> 'estimated_current';
  end if;

  return v_entry;
end;
$fn$;

comment on function public.add_to_day_basis(uuid, date, uuid, boolean) is
  '그날 기준에 없는 메뉴를 그 시점 값으로 더한다 — 순수 추가라 이미 기록된 숫자는 안 움직인다(0062). 종료된 장부에는 정정 경로에서만 더하고, 그때 basis_quality 를 estimated_current 로 내린다(0149).';

/*
 * ⚠ **몸통이다.** `p_allow_closed => true` 로 부르면 종료된 장부의 기준을 바꾸고
 *   basis_quality 를 내릴 수 있다 — 판본 검사도 감사 기록도 없이. 문은 정정 RPC 다.
 */
revoke execute on function public.add_to_day_basis(uuid, date, uuid, boolean)
  from public, anon, authenticated, service_role;


-- ── ④ 과거 정정은 그날 기준만 본다 ──────────────────────────────
do $m$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'e10_sale_recorded';
  if v_def is null then raise exception '0149: e10_sale_recorded 가 없습니다'; end if;
  if position('if not p_allow_closed and p_date > business_day()' in v_def) > 0 then return; end if;

  -- ④-1 미래 검사는 오늘 경로에서만. 정정 RPC 가 이미 매장 현지 날짜로 걸렀다.
  v_old := '  if p_date > business_day() then';
  if position(v_old in v_def) = 0 then
    raise exception '0149: e10 의 미래 날짜 검사를 못 찾았습니다';
  end if;
  v_def := replace(v_def, v_old, concat_ws(chr(10),
    '  /*',
    '   * ⚠ 이 검사는 **오늘 경로 전용**이다(0149). `business_day()` 는 매장을 안 가리는',
    '   *   전역 함수라 과거 정정에 쓰면 엉뚱한 날을 미래로 본다. 정정 RPC 는 이미',
    '   *   `sale_date_allowed(p_store, p_date)` 로 매장 현지 날짜 기준으로 걸렀다.',
    '   */',
    '  if not p_allow_closed and p_date > business_day() then'));

  -- ④-2 판매 중지는 **오늘** 파는 것을 막는 스위치다. 과거 기록에는 안 걸린다.
  v_old := '  if v_total > 0 then
    if not coalesce((select active from recipes where id = p_recipe), true) then';
  if position(v_old in v_def) = 0 then
    raise exception '0149: e10 의 판매 중지 검사를 못 찾았습니다';
  end if;
  v_def := replace(v_def, v_old, concat_ws(chr(10),
    '  /*',
    '   * ⚠ `판매 중지` 는 **오늘 파는 것**을 막는 스위치다(0149). 과거에 실제로 판 기록을',
    '   *   고치는 데는 안 걸린다 — 실측: 제육볶음을 중지하니 3일 전 수량 수정이 거절됐다.',
    '   *   과거 정정은 지금 파는지가 아니라 그날 무엇이 있었는지를 따른다.',
    '   */',
    '  if v_total > 0 and not p_allow_closed then',
    '    if not coalesce((select active from recipes where id = p_recipe), true) then'));

  -- ④-3 그날 기준에 없으면 더한다 — 종료된 장부에도.
  v_old := '    v_snap  := add_to_day_basis(p_store, p_date, p_recipe);';
  if position(v_old in v_def) = 0 then
    raise exception '0149: e10 의 add_to_day_basis 호출을 못 찾았습니다';
  end if;
  v_def := replace(v_def, v_old,
    '    v_snap  := add_to_day_basis(p_store, p_date, p_recipe, p_allow_closed);');

  execute v_def;
end $m$;


-- ── ⑤ 정정 응답의 basis_quality 는 몸통이 내린 뒤 값이다 ────────
do $m$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'amend_ended_business_day';
  if v_def is null then raise exception '0149: 정정 RPC 가 없습니다'; end if;
  if position('select basis_quality into v_day.basis_quality' in v_def) > 0 then return; end if;

  v_old := '  v_result := apply_sale_items(p_store, p_date, v_sales, p_items, p_etc_items, p_extra_items, true);';
  if position(v_old in v_def) = 0 then
    raise exception '0149: 정정 RPC 의 몸통 호출을 못 찾았습니다';
  end if;

  execute replace(v_def, v_old, concat_ws(chr(10),
    v_old,
    '',
    '  -- 몸통이 그날 기준을 못 찾아 현재값을 빌려 썼을 수 있다(0149).',
    '  -- 응답에 담기 전에 다시 읽는다 — 위에서 잡은 값은 그 이전 것이다.',
    '  select basis_quality into v_day.basis_quality from business_days where id = v_day.id;'));
end $m$;


-- ── 사후 확인 ────────────────────────────────────────────────────
do $v$
declare v_def text;
begin
  if (build_day_snapshot((select id from stores limit 1), current_date)->>'etc_tax_rate') is null then
    raise exception '0149: 스냅샷에 기타매출 세율이 없습니다';
  end if;

  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'apply_sale_items';
  if position('v_cur_items is distinct from p_etc_items' in v_def) = 0
     or position('day_etc_tax_rate' in v_def) = 0 then
    raise exception '0149: 몸통이 아직 현재 세율로 다시 계산합니다';
  end if;

  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'e10_sale_recorded';
  if position('if v_total > 0 and not p_allow_closed then' in v_def) = 0 then
    raise exception '0149: e10 가 아직 과거 정정에 판매 중지를 겁니다';
  end if;
  if position('if not p_allow_closed and p_date > business_day()' in v_def) = 0 then
    raise exception '0149: e10 가 아직 과거 정정에 전역 미래 검사를 겁니다';
  end if;
  if position('add_to_day_basis(p_store, p_date, p_recipe, p_allow_closed)' in v_def) = 0 then
    raise exception '0149: e10 가 종료 장부에 기준을 못 더합니다';
  end if;

  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'amend_ended_business_day';
  if position('select basis_quality into v_day.basis_quality' in v_def) = 0 then
    raise exception '0149: 정정 응답이 아직 옛 basis_quality 를 돌려줍니다';
  end if;
end $v$;

select public.assert_no_rpc_overloads();

/*
 * 0168 · 설정 값 계약 마무리 — 언어 키 이관 · 언어가 통화·금액 자릿수를 정한다 · JSON 타입 검사
 *
 * ① 언어 키 — DB 기본값·기존 행은 'ko-KR' 인데 0167 의 허용 목록(core LOCALES)은 'ko' 다.
 *    현재 값을 그대로 저장해도 INVALID_VALUE 로 실패했다(검토 실측). 기존 행을 core 키로 옮기고
 *    컬럼 기본값을 'ko' 로 바꾼다. 앱 fallback 도 'ko' 다.
 *
 * ② 언어 → 통화·금액 자릿수 — 언어 화면은 "언어가 통화와 금액 자릿수를 정한다"고 약속하는데
 *    앱은 locale 만 보냈다. en-US / KRW / 0자리 가 실제로 저장됐다(검토 실측). 서버가
 *    `locale_defaults()` 로 **원자적으로 파생**한다 — 같은 요청에 다른 통화·자릿수가 실리면 거부.
 *    표는 packages/core/src/locale.ts 의 LOCALES 와 같아야 한다(core 시험 localeSqlParity 가 이 파일을 읽어 대조).
 *
 * ③ JSON 타입 — 빈 {} 가 성공하며 updated_at 만 바뀌었고, "yes" 가 true 로, "abc" 컵 용량이
 *    원시 22P02 로 새어 나갔다(검토 실측). 비어 있지 않은 객체인지, 키마다 JSON 타입이 맞는지를
 *    값 검사 **앞에서** 보고 한 가지 코드(22000 · EMPTY_PAYLOAD / INVALID_VALUE)로 돌려준다.
 *
 * ④ 표 자체에도 CHECK 를 건다 — RPC 밖(소유자 직접 갱신·시드)에서도 같은 계약이 지켜지게.
 */

-- ── ② 언어 → 통화·금액 자릿수 (core LOCALES 미러) ──────────────
create or replace function public.locale_defaults(p_locale text)
returns table (currency text, money_digits int)
language sql
immutable
as $$
  select v.currency, v.money_digits
    from (values
      ('ko',    'KRW', 0),
      ('en-US', 'USD', 2),
      ('ja',    'JPY', 0),
      ('de',    'EUR', 2),
      ('ar-SA', 'SAR', 2),
      ('ar-AE', 'AED', 2),
      ('vi',    'VND', 0),
      ('es-ES', 'EUR', 2),
      ('es-MX', 'MXN', 2),
      ('pt-BR', 'BRL', 2)
    ) as v(locale, currency, money_digits)
   where v.locale = p_locale
$$;
comment on function public.locale_defaults(text) is
'언어 키 → 통화·금액 자릿수(0168). packages/core/src/locale.ts LOCALES 의 미러 — 두 표가 어긋나면 core 시험(localeSqlParity)이 빨개진다. 없는 키면 0행.';
revoke execute on function public.locale_defaults(text) from public, anon;
grant  execute on function public.locale_defaults(text) to authenticated, service_role;

-- ── ① 기존 행·기본값 이관 ────────────────────────────────────────
update public.settings set locale = case locale
    when 'ko-KR' then 'ko' when 'ko_KR' then 'ko'
    when 'en' then 'en-US' when 'en-GB' then 'en-US'
    when 'es' then 'es-ES' when 'ar' then 'ar-SA' when 'pt' then 'pt-BR'
    when 'ja-JP' then 'ja' when 'de-DE' then 'de' when 'vi-VN' then 'vi'
    else locale end
 where locale not in (select l from unnest(array['ko','en-US','ja','de','ar-SA','ar-AE','vi','es-ES','es-MX','pt-BR']) l);

do $$
declare v_bad text;
begin
  select string_agg(distinct locale, ', ') into v_bad
    from public.settings where not exists (select 1 from public.locale_defaults(locale));
  if v_bad is not null then
    raise exception '0168: 알 수 없는 언어 키가 남아 있습니다 — % (정리 후 다시 적용하세요)', v_bad;
  end if;
end $$;

-- 통화·금액 자릿수는 언어가 정한다 — 기존 행도 같은 규칙으로 맞춘다(en-US/KRW/0 같은 어긋남 정리).
update public.settings s
   set currency = d.currency, money_digits = d.money_digits
  from (select st.store_id, ld.currency, ld.money_digits
          from public.settings st, lateral public.locale_defaults(st.locale) ld) d
 where d.store_id = s.store_id
   and (s.currency is distinct from d.currency or s.money_digits is distinct from d.money_digits);

alter table public.settings alter column locale set default 'ko';

-- ── ④ 표의 CHECK — RPC 밖에서도 같은 계약 ───────────────────────
alter table public.settings drop constraint if exists settings_locale_ck;
alter table public.settings add constraint settings_locale_ck
  check (locale in ('ko','en-US','ja','de','ar-SA','ar-AE','vi','es-ES','es-MX','pt-BR'));
alter table public.settings drop constraint if exists settings_currency_ck;
alter table public.settings add constraint settings_currency_ck
  check (currency in ('KRW','USD','JPY','EUR','SAR','AED','VND','MXN','BRL'));
alter table public.settings drop constraint if exists settings_unit_system_ck;
alter table public.settings add constraint settings_unit_system_ck check (unit_system = 'metric');
alter table public.settings drop constraint if exists settings_cup_volume_ck;
alter table public.settings add constraint settings_cup_volume_ck check (cup_volume > 0 and cup_volume <= 5000);
alter table public.settings drop constraint if exists settings_target_rate_ck;
alter table public.settings add constraint settings_target_rate_ck
  check (default_target_profit_rate >= 0 and default_target_profit_rate <= 100);

-- ── ③ save_settings — 비어 있지 않은 객체 · JSON 타입 · 값 · 언어 파생 ──
create or replace function public.save_settings(p_store uuid, p_payload jsonb)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_unknown  text;
  v_key      text;
  v_num      numeric;
  v_locale   text;
  v_currency text;
  v_digits   int;
begin
  perform assert_my_store(p_store);   -- ⚠ 반드시 첫 줄
  perform lock_business_scope(p_store);   -- 0134 와 같은 순서

  -- 모양부터: 비어 있지 않은 객체여야 한다. 빈 저장이 성공하면 updated_at 만 바뀐다(검토 실측).
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception '설정은 객체로 보내 주세요' using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload = '{}'::jsonb then
    raise exception '저장할 설정 값이 없어요' using errcode = '22000', detail = 'EMPTY_PAYLOAD';
  end if;

  -- 영업시간은 여기로 안 들어온다(0163). 문은 하나다 — MY > 영업시간(판본 필수).
  if p_payload ?| array['open_time', 'close_time', 'break_start', 'break_end'] then
    raise exception '영업시간은 영업시간 화면에서만 바꿀 수 있어요'
      using errcode = '22000', detail = 'HOURS_NOT_HERE';
  end if;

  -- 모르는 키는 거부(0167) — 조용히 버리면 앱이 저장된 줄 안다.
  select string_agg(k, ', ') into v_unknown
    from jsonb_object_keys(p_payload) k
   where k not in ('locale', 'currency', 'unit_system', 'cup_volume',
                   'unit_price_digits', 'quantity_digits', 'money_digits',
                   'default_target_profit_rate',
                   'alert_morning_summary', 'alert_inbound_delay', 'alert_price_spike', 'alert_target_miss');
  if v_unknown is not null then
    raise exception '저장할 수 없는 설정이에요: %', v_unknown using errcode = '22000', detail = 'UNKNOWN_KEY';
  end if;

  -- JSON 타입(0168) — "yes" 는 참이 아니고 "abc" 는 숫자가 아니다. 캐스트보다 먼저 본다.
  foreach v_key in array array['locale', 'currency', 'unit_system'] loop
    if p_payload ? v_key and jsonb_typeof(p_payload -> v_key) <> 'string' then
      raise exception '%는 문자열이어야 해요', v_key using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end loop;
  foreach v_key in array array['cup_volume', 'unit_price_digits', 'quantity_digits', 'money_digits', 'default_target_profit_rate'] loop
    if p_payload ? v_key and jsonb_typeof(p_payload -> v_key) <> 'number' then
      raise exception '%는 숫자여야 해요', v_key using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end loop;
  foreach v_key in array array['alert_morning_summary', 'alert_inbound_delay', 'alert_price_spike', 'alert_target_miss'] loop
    if p_payload ? v_key and jsonb_typeof(p_payload -> v_key) <> 'boolean' then
      raise exception '%는 참/거짓이어야 해요', v_key using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end loop;

  -- 값(0167)
  if p_payload ? 'unit_system' and p_payload->>'unit_system' is distinct from 'metric' then
    raise exception '1차는 미터법만 지원해요' using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload ? 'cup_volume' then
    v_num := (p_payload->>'cup_volume')::numeric;
    if v_num <= 0 or v_num > 5000 then
      raise exception '컵 용량은 0 보다 크고 5,000ml 이하여야 해요' using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end if;
  foreach v_key in array array['unit_price_digits', 'quantity_digits', 'money_digits'] loop
    if p_payload ? v_key then
      v_num := (p_payload->>v_key)::numeric;
      if v_num <> trunc(v_num) or v_num < 0 or v_num > 4 then
        raise exception '자릿수는 0~4 사이 정수여야 해요 (%)', v_key using errcode = '22000', detail = 'INVALID_VALUE';
      end if;
    end if;
  end loop;
  if p_payload ? 'default_target_profit_rate' then
    v_num := (p_payload->>'default_target_profit_rate')::numeric;
    if v_num < 0 or v_num > 100 then
      raise exception '목표 이익률은 0~100%% 사이여야 해요' using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end if;

  insert into settings (store_id) values (p_store) on conflict (store_id) do nothing;

  /*
   * 언어가 통화·금액 자릿수를 정한다(0168). 새 언어가 오면 둘을 파생하고, 같은 요청에 다른
   * 값이 실려 있으면 거부한다 — 화면이 달러를 보여 주는데 원장이 원으로 남는 일을 막는다.
   * 언어 없이 통화·자릿수만 오면 현재 언어의 값과 같아야 한다.
   */
  select coalesce(p_payload->>'locale', s.locale) into v_locale from settings s where s.store_id = p_store;
  select d.currency, d.money_digits into v_currency, v_digits from locale_defaults(v_locale) d;
  if v_currency is null then
    raise exception '지원하지 않는 언어예요: %', v_locale using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload ? 'currency' and p_payload->>'currency' is distinct from v_currency then
    raise exception '통화는 언어가 정해요 (% → %)', v_locale, v_currency using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload ? 'money_digits' and (p_payload->>'money_digits')::int is distinct from v_digits then
    raise exception '금액 자릿수는 통화가 정해요 (% → %자리)', v_currency, v_digits using errcode = '22000', detail = 'INVALID_VALUE';
  end if;

  update settings set
    locale             = v_locale,
    currency           = v_currency,
    money_digits       = v_digits,
    unit_system        = coalesce(p_payload->>'unit_system', unit_system),
    cup_volume         = coalesce((p_payload->>'cup_volume')::numeric, cup_volume),
    unit_price_digits  = coalesce((p_payload->>'unit_price_digits')::int, unit_price_digits),
    quantity_digits    = coalesce((p_payload->>'quantity_digits')::int, quantity_digits),
    default_target_profit_rate = coalesce((p_payload->>'default_target_profit_rate')::numeric, default_target_profit_rate),
    alert_morning_summary = coalesce((p_payload->>'alert_morning_summary')::boolean, alert_morning_summary),
    alert_inbound_delay   = coalesce((p_payload->>'alert_inbound_delay')::boolean, alert_inbound_delay),
    alert_price_spike     = coalesce((p_payload->>'alert_price_spike')::boolean, alert_price_spike),
    alert_target_miss     = coalesce((p_payload->>'alert_target_miss')::boolean, alert_target_miss),
    updated_at         = now()
  where store_id = p_store;
end;
$$;
comment on function public.save_settings(uuid, jsonb) is
'설정 저장(언어·단위·컵·자릿수·목표율·알림). 비어 있지 않은 객체·JSON 타입·값을 검사하고(0168), 영업시간 키(HOURS_NOT_HERE)·모르는 키(UNKNOWN_KEY)·틀린 값(INVALID_VALUE)·빈 저장(EMPTY_PAYLOAD)은 22000. 통화·금액 자릿수는 언어에서 파생한다(locale_defaults). settings 는 앱 롤이 직접 못 쓰므로 definer(0164).';

-- ── 사후조건 ────────────────────────────────────────────────────
do $$
declare v_def text; v_n int;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = 'save_settings';
  if position('EMPTY_PAYLOAD' in v_def) = 0 or position('jsonb_typeof' in v_def) = 0
     or position('locale_defaults' in v_def) = 0 then
    raise exception '0168: save_settings 계약이 덜 됐습니다';
  end if;
  select count(*) into v_n from public.locale_defaults('ko') d where d.currency = 'KRW' and d.money_digits = 0;
  if v_n <> 1 then raise exception '0168: locale_defaults 가 ko 를 모릅니다'; end if;
  if (select column_default from information_schema.columns
       where table_schema = 'public' and table_name = 'settings' and column_name = 'locale') !~ '''ko''' then
    raise exception '0168: settings.locale 기본값이 ko 가 아닙니다';
  end if;
  select count(*) into v_n from public.settings s
   where not exists (select 1 from public.locale_defaults(s.locale) d
                      where d.currency = s.currency and d.money_digits = s.money_digits);
  if v_n > 0 then
    raise exception '0168: 언어와 통화·자릿수가 어긋난 행이 %개 있습니다', v_n;
  end if;
  foreach v_def in array array['settings_locale_ck','settings_currency_ck','settings_unit_system_ck','settings_cup_volume_ck','settings_target_rate_ck'] loop
    if not exists (select 1 from pg_constraint where conname = v_def and conrelid = 'public.settings'::regclass and convalidated) then
      raise exception '0168: 제약 % 가 없거나 검증되지 않았습니다', v_def;
    end if;
  end loop;
end $$;

/*
 * 0172 · 설정 판본 완결 — 무변경 저장은 자국을 남기지 않고 세금 설정도 같은 판본을 쓴다
 *
 * 0171 은 일반 설정에 판본을 붙였지만, 같은 값을 다시 저장해도 revision·updated_at 을
 * 올렸다. 또 save_store_tax 는 같은 settings 행의 tax_mode·tax_items 를 쓰면서 판본을
 * 검사하지 않아 두 기기의 세금 항목 배열이 서로를 조용히 덮을 수 있었다.
 *
 * 규칙:
 *   · 두 저장문 모두 p_base_revision 을 요구한다(null → 22000 BASE_REQUIRED).
 *   · 현재 판본과 다르면 45009 REVISION_CONFLICT 로 거부한다.
 *   · 실제 값이 같으면 UPDATE 자체를 하지 않고 changed=false, revision=현재값을 돌려준다.
 *     settings_touch 트리거가 UPDATE 만으로 updated_at 을 바꾸므로 WHERE 가드만으로는 부족하다.
 *   · 실제 값이 바뀐 경우에만 revision + 1, updated_at 갱신 및 세금 전파를 수행한다.
 */

-- ── ① 일반 설정 — 동일 값은 UPDATE 하지 않는다 ─────────────────
drop function if exists public.save_settings(uuid, jsonb);

create or replace function public.save_settings(
  p_store uuid,
  p_payload jsonb,
  p_base_revision integer default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_unknown  text;
  v_key      text;
  v_num      numeric;
  v_locale   text;
  v_currency text;
  v_digits   int;
  v_rev      int;
begin
  perform assert_my_store(p_store);       -- ⚠ definer 문지기: 반드시 첫 줄
  perform lock_business_scope(p_store);   -- 다른 설정 저장과 잠금 순서 통일

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception '설정은 객체로 보내 주세요' using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload = '{}'::jsonb then
    raise exception '저장할 설정 값이 없어요' using errcode = '22000', detail = 'EMPTY_PAYLOAD';
  end if;

  if p_payload ?| array['open_time', 'close_time', 'break_start', 'break_end'] then
    raise exception '영업시간은 영업시간 화면에서만 바꿀 수 있어요'
      using errcode = '22000', detail = 'HOURS_NOT_HERE';
  end if;

  select string_agg(k, ', ') into v_unknown
    from jsonb_object_keys(p_payload) k
   where k not in ('locale', 'currency', 'unit_system', 'cup_volume',
                   'unit_price_digits', 'quantity_digits', 'money_digits',
                   'default_target_profit_rate',
                   'alert_morning_summary', 'alert_inbound_delay', 'alert_price_spike', 'alert_target_miss');
  if v_unknown is not null then
    raise exception '저장할 수 없는 설정이에요: %', v_unknown using errcode = '22000', detail = 'UNKNOWN_KEY';
  end if;

  foreach v_key in array array['locale', 'currency', 'unit_system'] loop
    if p_payload ? v_key and jsonb_typeof(p_payload -> v_key) <> 'string' then
      raise exception '%는 문자열이어야 해요', v_key using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end loop;
  foreach v_key in array array['cup_volume', 'unit_price_digits', 'quantity_digits', 'money_digits', 'default_target_profit_rate'] loop
    if p_payload ? v_key and jsonb_typeof(p_payload -> v_key) <> 'number' then
      raise exception '%는 숫자여야 해요', v_key using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end loop;
  foreach v_key in array array['alert_morning_summary', 'alert_inbound_delay', 'alert_price_spike', 'alert_target_miss'] loop
    if p_payload ? v_key and jsonb_typeof(p_payload -> v_key) <> 'boolean' then
      raise exception '%는 참/거짓이어야 해요', v_key using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end loop;

  if p_payload ? 'unit_system' and p_payload->>'unit_system' is distinct from 'metric' then
    raise exception '1차는 미터법만 지원해요' using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload ? 'cup_volume' then
    v_num := (p_payload->>'cup_volume')::numeric;
    if v_num <= 0 or v_num > 5000 then
      raise exception '컵 용량은 0 보다 크고 5,000ml 이하여야 해요' using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end if;
  foreach v_key in array array['unit_price_digits', 'quantity_digits', 'money_digits'] loop
    if p_payload ? v_key then
      v_num := (p_payload->>v_key)::numeric;
      if v_num <> trunc(v_num) or v_num < 0 or v_num > 4 then
        raise exception '자릿수는 0~4 사이 정수여야 해요 (%)', v_key using errcode = '22000', detail = 'INVALID_VALUE';
      end if;
    end if;
  end loop;
  if p_payload ? 'default_target_profit_rate' then
    v_num := (p_payload->>'default_target_profit_rate')::numeric;
    if v_num < 0 or v_num > 100 then
      raise exception '목표 이익률은 0~100%% 사이여야 해요' using errcode = '22000', detail = 'INVALID_VALUE';
    end if;
  end if;

  insert into settings (store_id) values (p_store) on conflict (store_id) do nothing;

  select s.revision into v_rev from settings s where s.store_id = p_store for update;
  if p_base_revision is null then
    raise exception '설정 판본이 필요해요 — 설정을 다시 불러온 뒤 저장해 주세요'
      using errcode = '22000', detail = 'BASE_REQUIRED';
  end if;
  if p_base_revision <> v_rev then
    raise exception '다른 기기에서 설정이 변경됐어요. 새로고침 후 다시 저장해 주세요'
      using errcode = '45009', detail = 'REVISION_CONFLICT';
  end if;

  select coalesce(p_payload->>'locale', s.locale) into v_locale
    from settings s where s.store_id = p_store;
  select d.currency, d.money_digits into v_currency, v_digits from locale_defaults(v_locale) d;
  if v_currency is null then
    raise exception '지원하지 않는 언어예요: %', v_locale using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload ? 'currency' and p_payload->>'currency' is distinct from v_currency then
    raise exception '통화는 언어가 정해요 (% → %)', v_locale, v_currency using errcode = '22000', detail = 'INVALID_VALUE';
  end if;
  if p_payload ? 'money_digits' and (p_payload->>'money_digits')::int is distinct from v_digits then
    raise exception '금액 자릿수는 통화가 정해요 (% → %자리)', v_currency, v_digits using errcode = '22000', detail = 'INVALID_VALUE';
  end if;

  /*
   * target 값이 현재 행과 하나라도 다를 때만 UPDATE 한다. settings_touch 가 UPDATE 마다
   * updated_at 을 다시 쓰므로, UPDATE 후 changed 를 계산하면 이미 자국이 남는다.
   */
  update settings set
    locale             = v_locale,
    currency           = v_currency,
    money_digits       = v_digits,
    unit_system        = coalesce(p_payload->>'unit_system', unit_system),
    cup_volume         = coalesce((p_payload->>'cup_volume')::numeric, cup_volume),
    unit_price_digits  = coalesce((p_payload->>'unit_price_digits')::int, unit_price_digits),
    quantity_digits    = coalesce((p_payload->>'quantity_digits')::int, quantity_digits),
    default_target_profit_rate = coalesce((p_payload->>'default_target_profit_rate')::numeric, default_target_profit_rate),
    alert_morning_summary = coalesce((p_payload->>'alert_morning_summary')::boolean, alert_morning_summary),
    alert_inbound_delay   = coalesce((p_payload->>'alert_inbound_delay')::boolean, alert_inbound_delay),
    alert_price_spike     = coalesce((p_payload->>'alert_price_spike')::boolean, alert_price_spike),
    alert_target_miss     = coalesce((p_payload->>'alert_target_miss')::boolean, alert_target_miss),
    revision           = revision + 1,
    updated_at         = now()
  where store_id = p_store
    and (locale is distinct from v_locale
      or currency is distinct from v_currency
      or money_digits is distinct from v_digits
      or unit_system is distinct from coalesce(p_payload->>'unit_system', unit_system)
      or cup_volume is distinct from coalesce((p_payload->>'cup_volume')::numeric, cup_volume)
      or unit_price_digits is distinct from coalesce((p_payload->>'unit_price_digits')::int, unit_price_digits)
      or quantity_digits is distinct from coalesce((p_payload->>'quantity_digits')::int, quantity_digits)
      or default_target_profit_rate is distinct from coalesce((p_payload->>'default_target_profit_rate')::numeric, default_target_profit_rate)
      or alert_morning_summary is distinct from coalesce((p_payload->>'alert_morning_summary')::boolean, alert_morning_summary)
      or alert_inbound_delay is distinct from coalesce((p_payload->>'alert_inbound_delay')::boolean, alert_inbound_delay)
      or alert_price_spike is distinct from coalesce((p_payload->>'alert_price_spike')::boolean, alert_price_spike)
      or alert_target_miss is distinct from coalesce((p_payload->>'alert_target_miss')::boolean, alert_target_miss))
  returning revision into v_rev;

  if not found then
    return jsonb_build_object('changed', false, 'revision', p_base_revision);
  end if;
  return jsonb_build_object('changed', true, 'revision', v_rev);
end;
$$;

comment on function public.save_settings(uuid, jsonb, integer) is
'설정 저장(0172). p_base_revision 필수(null=22000 BASE_REQUIRED, 불일치=45009 REVISION_CONFLICT). 실제 값이 바뀔 때만 settings 를 UPDATE 하고 revision+1·updated_at 갱신. 무변경은 changed=false 와 현재 revision, 변경은 changed=true 와 새 revision을 돌려준다. 통화·금액 자릿수는 locale_defaults 에서 파생한다.';
revoke execute on function public.save_settings(uuid, jsonb, integer) from public, anon;
grant  execute on function public.save_settings(uuid, jsonb, integer) to authenticated, service_role;

-- ── ② 세금 설정 — 같은 settings.revision 으로 보호한다 ──────────
drop function if exists public.save_store_tax(uuid, tax_mode, jsonb);

create or replace function public.save_store_tax(
  p_store uuid,
  p_mode tax_mode,
  p_items jsonb,
  p_base_revision integer default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_mode0  tax_mode;
  v_items0 jsonb;
  v_items  jsonb;
  v_day    date;
  v_month  text;
  v_rate   numeric;
  v_corr   uuid := gen_random_uuid();
  v_ext    numeric;
  v_t0     numeric;
  v_t1     numeric;
  v_rev    integer;
  rec      record;
  v_n      int := 0;
begin
  perform assert_my_store(p_store);       -- ⚠ definer 문지기: 반드시 첫 줄
  perform lock_business_scope(p_store);   -- save_settings 와 같은 잠금 순서

  v_day   := store_local_date(p_store);
  v_month := to_char(v_day, 'YYYY-MM');
  v_items := assert_tax_items(coalesce(p_items, '[]'::jsonb));

  insert into settings (store_id) values (p_store) on conflict (store_id) do nothing;

  select tax_mode, tax_items, revision into v_mode0, v_items0, v_rev
    from settings where store_id = p_store for update;
  if not found then
    raise exception '매장 설정을 찾지 못했어요' using errcode = '22000';
  end if;
  if p_base_revision is null then
    raise exception '설정 판본이 필요해요 — 설정을 다시 불러온 뒤 저장해 주세요'
      using errcode = '22000', detail = 'BASE_REQUIRED';
  end if;
  if p_base_revision <> v_rev then
    raise exception '다른 기기에서 설정이 변경됐어요. 새로고침 후 다시 저장해 주세요'
      using errcode = '45009', detail = 'REVISION_CONFLICT';
  end if;

  -- 같으면 UPDATE·전파·감사 기록을 모두 건너뛴다.
  if v_mode0 is not distinct from p_mode and coalesce(v_items0, '[]'::jsonb) = v_items then
    return jsonb_build_object('changed', false, 'recipes', 0, 'revision', v_rev);
  end if;

  update settings
     set tax_mode = p_mode,
         tax_items = v_items,
         revision = revision + 1,
         updated_at = now()
   where store_id = p_store
   returning revision into v_rev;
  if not found then
    raise exception '매장 설정을 찾지 못했어요' using errcode = '22000';
  end if;

  v_rate := coalesce(fixed_cost_rate(p_store, v_month), 0);
  for rec in select id, price from recipes where store_id = p_store and coalesce(active, true) loop
    v_t0 := tax_of(rec.price, v_mode0, coalesce(v_items0, '[]'::jsonb));
    v_t1 := tax_of(rec.price, p_mode, v_items);

    update recipes set updated_at = now() where id = rec.id;
    perform recompute_recipe(rec.id, 'tax', v_day);
    v_n := v_n + 1;

    v_ext := coalesce((select sum(ec.amount_per_serving)
                         from recipe_extra_costs ec where ec.recipe_id = rec.id), 0);
    perform record_entity_change(
      p_store, 'recipe', rec.id, 'fixed_cost', '세금 반영',
      change_line('tax', '세금', round(v_t0, 2), round(v_t1, 2), '원', 'derived')
      || change_line('profit', '순이익',
           round(rec.price - recipe_material_cost(rec.id) - v_ext - v_t0 - v_rate * rec.price, 2),
           round(rec.price - recipe_material_cost(rec.id) - v_ext - v_t1 - v_rate * rec.price, 2),
           '원', 'derived'),
      true, null, v_corr, '세금 설정 변경');
  end loop;

  return jsonb_build_object('changed', true, 'recipes', v_n,
                            'mode', p_mode, 'items', v_items, 'revision', v_rev);
end;
$$;

comment on function public.save_store_tax(uuid, tax_mode, jsonb, integer) is
'매장 세금 설정 저장(0172). p_base_revision 필수(null=22000 BASE_REQUIRED, 불일치=45009 REVISION_CONFLICT). 실제 세금 값이 바뀔 때만 settings.revision+1·updated_at 갱신 후 활성 레시피에 전파하고, 무변경은 자국 없이 changed=false 와 현재 revision을 돌려준다.';
revoke execute on function public.save_store_tax(uuid, tax_mode, jsonb, integer) from public, anon;
grant  execute on function public.save_store_tax(uuid, tax_mode, jsonb, integer) to authenticated, service_role;

-- ── ③ 사후조건 ─────────────────────────────────────────────────
do $$
declare
  v_def text;
begin
  if exists (
    select 1 from pg_proc p
     where p.pronamespace = 'public'::regnamespace
       and ((p.proname = 'save_settings' and p.pronargs <> 3)
         or (p.proname = 'save_store_tax' and p.pronargs <> 4))
  ) then
    raise exception '0172: 설정 저장 RPC 의 옛 시그니처가 남아 있습니다';
  end if;

  select pg_get_functiondef('public.save_settings(uuid,jsonb,integer)'::regprocedure) into v_def;
  if position('''changed'', false' in v_def) = 0
     or position('revision + 1' in v_def) = 0
     or position('REVISION_CONFLICT' in v_def) = 0 then
    raise exception '0172: save_settings 무변경·판본 계약이 덜 됐습니다';
  end if;

  select pg_get_functiondef('public.save_store_tax(uuid,tax_mode,jsonb,integer)'::regprocedure) into v_def;
  if position('''changed'', false' in v_def) = 0
     or position('revision = revision + 1' in v_def) = 0
     or position('REVISION_CONFLICT' in v_def) = 0 then
    raise exception '0172: save_store_tax 무변경·판본 계약이 덜 됐습니다';
  end if;
end $$;
